<!doctype html><html lang="id"><head><meta charset="utf-8"><style>@page{margin:22mm 14mm 18mm}body{font-family:DejaVu Sans,sans-serif;color:#0f172a;font-size:10px}h1{font-size:19px;margin:0 0 4px}.muted{color:#64748b}.notice{margin:12px 0;padding:8px;background:#eff6ff;border:1px solid #bfdbfe}.stats{width:100%;margin:12px 0;border-collapse:separate;border-spacing:5px}.stats td{background:#f8fafc;padding:8px;border:1px solid #e2e8f0}.stats strong{display:block;font-size:15px;margin-top:3px}.chart{height:110px;border-bottom:1px solid #94a3b8;white-space:nowrap;margin:12px 0}.bar-wrap{display:inline-block;width:28px;height:110px;margin-right:4px;vertical-align:bottom;text-align:center}.bar-space{height:90px;position:relative}.bar{position:absolute;bottom:0;left:4px;width:20px;background:#0ea5e9}.bar-label{font-size:7px}table.history{width:100%;border-collapse:collapse;table-layout:fixed}.history th,.history td{border:1px solid #cbd5e1;padding:5px;word-wrap:break-word}.history th{background:#e2e8f0}.history tr{page-break-inside:avoid}.footer{position:fixed;bottom:-10mm;left:0;right:0;text-align:center;color:#64748b;font-size:8px}</style></head><body><h1>Histori Kuis Latihan</h1><div class="muted">{{ $companyProfile['name'] ?? config('app.name') }} · {{ $title }}</div><p><strong>Nama:</strong> {{ $student['Full_Name'] ?? $student['Student_Name'] ?? $student['Student_ID'] }}<br><strong>ID siswa:</strong> {{ $student['Student_ID'] }} · <strong>Kelas:</strong> {{ $student['Class_ID'] ?? '-' }}<br><strong>Periode:</strong> {{ $filters['from'] ?? 'awal' }} s.d. {{ $filters['to'] ?? 'sekarang' }} · <strong>Dicetak:</strong> {{ $generatedAt->locale('id')->translatedFormat('d F Y H:i') }}</p><div class="notice">Hasil kuis latihan bukan bagian dari nilai akademik, rapor, kelulusan resmi JFT, atau peringkat siswa/kelas.</div><table class="stats"><tr><td>Percobaan<strong>{{ $stats['count'] }}</strong></td><td>Terakhir<strong>{{ $stats['last'] === null ? '-' : number_format($stats['last'],2) }}</strong></td><td>Terbaik<strong>{{ $stats['best'] === null ? '-' : number_format($stats['best'],2) }}</strong></td><td>Terendah<strong>{{ $stats['lowest'] === null ? '-' : number_format($stats['lowest'],2) }}</strong></td><td>Rata-rata<strong>{{ $stats['average'] === null ? '-' : number_format($stats['average'],2) }}</strong></td></tr></table>@if($stats['chart']->isNotEmpty())<h2>Perkembangan Nilai</h2><div class="chart">@foreach($stats['chart'] as $point)<div class="bar-wrap"><div>{{ number_format($point['score'],0) }}</div><div class="bar-space"><div class="bar" style="height:{{ max(2,$point['score']*.9) }}px"></div></div><div class="bar-label">#{{ $point['attempt'] }}</div></div>@endforeach</div>@endif<h2>Riwayat Pengerjaan</h2><table class="history"><thead><tr><th style="width:25%">Latihan</th><th>Perc.</th><th style="width:19%">Selesai</th><th>Durasi</th><th>Nilai</th><th>B/S/K</th><th>Status</th></tr></thead><tbody>@foreach($rows as $row)<tr><td>{{ $row->Quiz_Title }}<br><span class="muted">Revision {{ substr($row->Revision_ID,0,8) }}</span></td><td>#{{ $row->Attempt_Number }}</td><td>{{ \Carbon\Carbon::parse($row->Completed_At)->format('d-m-Y H:i') }}</td><td>{{ intdiv($row->Duration_Seconds,60) }}m {{ $row->Duration_Seconds%60 }}d</td><td>{{ number_format($row->Normalized_Score,2) }}</td><td>{{ $row->Correct_Count }}/{{ $row->Incorrect_Count }}/{{ $row->Unanswered_Count }}</td><td>{{ $row->Attempt_Status==='EXPIRED'?'Waktu habis':'Selesai' }}</td></tr>@endforeach</tbody></table><div class="footer">Dokumen dibuat otomatis oleh WMS dari data server-side milik siswa.</div></body></html>
